package com.bts.viewplustest.friend; import com.bts.viewplustest.user.User; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="user_friends",uniqueConstraints=@UniqueConstraint(name="uk_friend_pair",columnNames={"requester_user_id","addressee_user_id"})) public class UserFriend { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="requester_user_id") private User requester; @ManyToOne(optional=false) @JoinColumn(name="addressee_user_id") private User addressee; @Enumerated(EnumType.STRING) @Column(nullable=false) private FriendStatus status=FriendStatus.PENDING; @Column(nullable=false) private Instant createdAt=Instant.now(); protected UserFriend(){} public UserFriend(User r,User a){requester=r;addressee=a;} public Long getId(){return id;} public User getRequester(){return requester;} public User getAddressee(){return addressee;} public FriendStatus getStatus(){return status;} public void accept(){status=FriendStatus.ACCEPTED;} }
